  "Obra de ficção / história alternativa. Não representa fatos nem endosso. Progresso salvo automaticamente neste navegador, separado por cenário. Funciona offline e sem conta; com login, os saves e finais também vão para a nuvem.": "虚构作品／架空历史。不代表事实，也不代表认同。进度自动保存在此浏览器中，按剧本分开。离线、无账号也能玩；登录后，存档和结局也会同步到云端。",
