  "Indisponível por enquanto": "暂不可用",
  "Ficção de história alternativa, no estilo de mods de jogos de estratégia. Tudo o que acontece a partir da primeira escolha é inventado: não retrata fatos, não é previsão e não representa endosso a nenhuma pessoa, partido ou ação. Personagens reais aparecem apenas em papéis públicos, sem falas atribuídas. Golpe de Estado é crime contra a democracia — no jogo, ele tem as consequências que tem.": "架空历史虚构作品，采用策略游戏模组的风格。从第一个选择开始发生的一切都是虚构的：不反映事实，不是预测，也不代表对任何个人、政党或行动的认同。真实人物仅以公开身份出现，不为其编造台词。政变是危害民主的罪行——在游戏中，它会带来应有的后果。",
