  "explica a agitação em detalhes.": "详细解释动荡。",
  "Estados": "州",
  "Passe o mouse (ou toque) para ver controle e agitação. Clique num estado para abrir o painel ao lado:": "将鼠标悬停（或点按）查看控制和动荡。点击一个州打开旁边的面板：",
  "Painel lateral": "侧边面板",
  "Mostra o estado ou exército selecionado. Sem seleção, mostra o resumo do país e as frentes de combate.": "显示所选的州或军队。未选择时，显示全国概况和战线。",
  "contadores azuis": "蓝色棋子",
