  "força": "兵力",
  ". Os vermelhos são inimigos.": "。红色的是敌军。",
  "Clique num exército e depois num estado vizinho destacado:": "点击一支军队，再点击一个高亮的相邻州：",
  "vermelho = atacar": "红色 = 进攻",
  "azul = mover": "蓝色 = 调动",
  ". A previsão da batalha aparece antes de confirmar.": "。确认前会显示战斗预测。",
