  ": um projeto de alguns meses. Escolha": "：一个为期数月的项目。一次只能选",
  "um por vez": "一个",
  "Navegação:": "浏览：",
  "arraste para mover, use a roda do mouse ou o trackpad para rolar e": "拖动来移动，用鼠标滚轮或触控板滚动，",
  "Ctrl + roda": "Ctrl + 滚轮",
  "(ou pinça no celular) para o zoom.": "（手机上用双指）缩放。",
  "Como ler a árvore": "如何阅读决策树",
  "Linhas sólidas: pré-requisito. Tracejadas: basta um.": "实线：前置条件。虚线：任选其一。",
  "⊘ vermelho": "红色 ⊘",
  ": caminhos exclusivos — escolher um fecha o outro. Decisões da história também abrem e fecham ramos.": "：互斥路线——选了一条就会关闭另一条。故事中的决定也会开启和关闭分支。",
  "Zoom e tela cheia": "缩放与全屏",
