  "Razão de forças": "兵力比",
  "Inimigo": "敌方",
  "defendendo": "防守中",
  "Milícias e guerrilheiros": "民兵和游击队",
  "Terreno: Serras": "地形：山地",
  "Qualidade das tropas": "部队素质",
  "Comparação de forças": "兵力对比",
  "Fator": "因素",
  "Você": "你",
  "Favoreceu": "占优方",
  "Tropas (força total)": "部队（总兵力）",
  "você": "你",
  "Moral / organização média": "平均士气／组织度",
  "Experiência média": "平均经验",
  "Comando e lealdade militar": "指挥与军方忠诚度",
  "Terreno": "地形",
  "💡 Boa chance: mande o ataque com estes exércitos.": "💡 胜算较大：派这些军队发起进攻。",
  "Batalha": "战斗",
  "Poder de combate inicial = força × moral × experiência × modificadores": "初始战斗力 = 兵力 × 士气 × 经验 × 修正值",
  "Seu lado": "你方",
  "Peso econômico": "经济分量",
  "Vizinhos": "相邻州",
  "Forças no estado": "该州兵力",
  "Polícia e milícias leais": "忠诚的警察和民兵",
  "Investir recursos": "投入资源",
  "Negociar com o governador": "与州长谈判",
  "Voltar à visão geral": "返回总览",
  "O Mundo Reage": "世界作出反应",
  "Estados Unidos, União Europeia e quase todos os vizinhos sul-americanos se recusam a reconhecer o novo governo. O Mercosul suspende o Brasil, bancos estrangeiros congelam linhas de crédito e o real perde um terço do valor em duas semanas.": "美国、欧盟和几乎所有南美邻国都拒绝承认新政府。南共市暂停巴西的成员资格，外国银行冻结信贷额度，雷亚尔在两周内贬值三分之一。",
  "Nos supermercados, os preços sobem dia após dia. Exportadores do agronegócio — parte da sua base — ligam desesperados: contratos estão sendo cancelados.": "超市里的价格一天比一天高。农业综合企业的出口商——你基本盘的一部分——绝望地打来电话：合同正在被取消。",
  "Prometer eleições supervisionadas para obter reconhecimento.": "承诺举行受监督的选举以换取承认。",
  "Buscar apoio em governos simpáticos e ignorar o Ocidente.": "寻求友好政府的支持，无视西方。",
