  "Final: O Brasil Partido": "结局：分裂的巴西",
  "Três Bandeiras": "三面旗帜",
  "O cessar-fogo vira fronteira. Brasília controla o Centro-Sul; o governo constitucional, o Norte e o Nordeste; a Liga do Sul hasteia sua própria bandeira entre o Paraná e o Uruguai. Minas Gerais continua cortada por trincheiras.": "停火线变成了国界。巴西利亚控制中南部；宪政政府控制北部和东北部；南方联盟在巴拉那和乌拉圭之间升起了自己的旗帜。米纳斯吉拉斯依然被战壕割裂。",
  "Diplomatas falam em \"conflito congelado\". Nas famílias separadas pela linha de frente, ninguém usa essa palavra. A guerra de separação que muitos julgavam impossível tornou-se o novo normal.": "外交官们称之为“冻结的冲突”。在被战线拆散的家庭里，没有人用这个词。许多人曾以为不可能发生的分裂战争，成了新的常态。",
