  "Reunir números, aliados e danos da eleição perdida antes de decidir o rumo.": "在决定方向之前，先清点败选后的票数、盟友和损失。",
  "Assumir publicamente o papel de oposição dentro da Constituição. Acalma instituições e parceiros externos; parte da base se frustra.": "公开扮演宪法框架内的反对派角色。安抚国家制度和外国伙伴；部分基本盘会感到失望。",
  "Questionar o processo pelos canais legais — tribunais, Congresso e auditorias — sem romper com as instituições.": "通过法律渠道——法院、国会和审计——质疑选举过程，而不与国家制度决裂。",
  "Conversas reservadas sobre caminhos fora da Constituição. Golpe de Estado é crime: no jogo, este ramo tem custos pesados e pode fracassar.": "私下商讨宪法之外的途径。政变是犯罪：在游戏中，这条分支代价沉重，而且可能失败。",
  "Montar um gabinete paralelo de conselheiros. Abre as agendas de economia, diplomacia e sociedade.": "组建由顾问组成的影子内阁。开启经济、外交和社会议程。",
  "Organizar a bancada e ocupar o espaço de principal voz da oposição.": "组织议会党团，成为反对派的主要声音。",
  "Trocar pureza por votos no Congresso: cargos, palanques e acordos regionais.": "以纯粹性换取国会选票：职位、竞选台和地区协议。",
  "Recusar alianças de ocasião e falar só com a base fiel.": "拒绝权宜联盟，只对忠实的基本盘讲话。",
  "Encomendar uma auditoria técnica independente. Agrada a base; os tribunais e observadores veem com desconfiança.": "委托进行独立技术审计。讨好基本盘；法院和观察人士心存疑虑。",
  "Contratar uma banca respeitada e trocar ataques por petições.": "聘请一家有声望的律师事务所，以诉状代替攻击。",
  "Propor mandatos e limites para tribunais superiores. Mobiliza a base e abre guerra com o Judiciário.": "提议为高等法院设定任期和限制。动员基本盘，并与司法机构开战。",
  "Baixar a temperatura com tribunais e Congresso em troca de previsibilidade.": "与法院和国会降温，以换取可预期性。",
  "Costurar no Congresso um projeto de anistia ampla. Ajuda no capítulo 'Nos Tribunais', mas tensiona o Judiciário.": "在国会拼凑一项全面大赦法案。对“在法庭上”一章有帮助，但会激化与司法机构的关系。",
  "Agrados e reuniões com comandantes. Deixa rastros: a conspiração passa a constar nos autos (bloqueia a defesa limpa em 'Nos Tribunais').": "拉拢并会见司令官。会留下痕迹：密谋将被记入卷宗（封锁“在法庭上”中的清白辩护）。",
  "Redigir um decreto de exceção. Aumenta a chance de adesão militar — e a gravidade de um fracasso.": "起草紧急状态法令。提高军方加入的可能性——也加重失败的后果。",
  "Formalizar o regime: toque de recolher, prisões e governo por decreto. Custo humano e isolamento crescentes.": "使政权正式化：宵禁、逮捕和以法令治国。人员代价和孤立日益加剧。",
  "Afastar governadores que resistem e nomear interventores militares.": "撤换抵抗的州长，任命军方干预官。",
  "Anunciar um calendário eleitoral supervisionado para reduzir o isolamento.": "宣布受监督的选举时间表，以减少孤立。",
  "Um só estado-maior para todas as frentes.": "所有战线由同一个总参谋部指挥。",
  "Construção de Estado: uma carta provisória para dar forma jurídica ao regime. Poucos dentro e fora a reconhecem.": "国家建构：一部临时宪章，为政权提供法律形式。国内外很少有人承认它。",
  "Convocação de reservistas. Mais tropas, mais medo, menos economia.": "征召预备役。更多部队，更多恐惧，经济更差。",
  "Concentrar forças para quebrar a resistência constitucional. Enfraquece o inimigo por alguns meses.": "集中兵力粉碎宪政抵抗力量。使敌人在几个月内被削弱。",
  "Controle de preços, requisições e câmbio fixo.": "价格管制、征用和固定汇率。",
  "Abrir uma segunda frente contra os separatistas do Sul.": "开辟对南方分离主义者的第二战线。",
  "Trégua de conveniência com os separatistas: reconhece fato consumado e divide o comando.": "与分离主义者达成权宜休战：承认既成事实并分享指挥权。",
  "Ofensiva diplomática junto a governos dispostos a ignorar a ruptura.": "向愿意无视断裂的政府发起外交攻势。",
  "Compromissos com entidades do agronegócio: crédito, infraestrutura e segurança no campo.": "向农业综合企业团体作出承诺：信贷、基础设施和农村安全。",
  "Um programa de concessões e venda de estatais — aplaudido pelo mercado, combatido por sindicatos.": "特许经营和出售国有企业的计划——受到市场欢迎，遭到工会反对。",
  "Soja, minério e petróleo como cartas na mesa. Libera promessas de commodities também na oposição.": "把大豆、矿石和石油当作谈判筹码。在野时也能开启大宗商品承诺。",
  "Priorizar o maior comprador do Brasil: financiamento e infraestrutura.": "优先考虑巴西最大的买家：融资和基础设施。",
  "Acordos com investidores e o mercado norte-americano, com distância de Pequim.": "与投资者和美国市场达成协议，与北京保持距离。",
  "Agendas com parlamentares, think tanks e diplomatas ocidentais. Libera promessas de cooperação em defesa.": "与西方议员、智库和外交官会面。开启防务合作承诺。",
  "Aproximação com China, Rússia e o Sul Global.": "与中国、俄罗斯和全球南方走近。",
  "Agenda regional com governadores de fronteira e vizinhos.": "与边境州长和邻国开展地区议程。",
  "Laços com partidos e governos afins na região. Aproxima uns, afasta outros.": "与地区内志同道合的政党和政府建立联系。拉近一些，疏远另一些。",
  "Encontros regulares com lideranças religiosas e suas bancadas.": "定期会见宗教领袖及其议会党团。",
  "Propostas duras contra o crime organizado. Popular, polêmica entre movimentos sociais.": "严厉打击有组织犯罪的提案。受欢迎，但在社会运动中有争议。",
  "Estrutura profissional de conteúdo e mobilização digital. Alcance enorme, atrito com tribunais e plataformas.": "专业的内容生产和网络动员体系。影响力巨大，与法院和平台产生摩擦。",
  "Entrevistas, coletivas e menos ataques a jornalistas.": "接受采访、召开记者会，减少对记者的攻击。",
  "Projetos de valores familiares e religiosos como bandeira da oposição.": "把家庭和宗教价值观法案作为反对派的旗帜。",
