  "— o número grande mostra quantas sobram neste mês (depende do Apoio Militar e da lealdade das Forças). Defender e reforçar são livres.": "——大数字显示本月还剩多少（取决于军方支持和武装部队忠诚度）。防守和增援不受限制。",
