  "ações da categoria": "以下类别的行动",
  ", investir ou negociar nesses estados e, com a tensão baixa, o": "、在这些州投资或谈判，并在紧张度较低时达成",
  ", que torna o Sul seu aliado.": "，让南方成为你的盟友。",
  "Clique na barra para ver o que sobe, o que baixa e agir.": "点击进度条，查看什么会使其上升、什么会使其下降，并采取行动。",
  "Ações do governo por área (após o golpe, também": "按领域划分的政府行动（政变后，还有",
  "). Cada uma mostra o custo (": "）。每项都会显示费用（",
  "A Liga do Sul se rebela": "南方联盟叛乱",
  "Os governadores do Sul rompem com Brasília. A revolta começa pequena — um estado e um exército modesto — e ainda pode ser contida.": "南方州长们与巴西利亚决裂。叛乱起初规模不大——一个州和一支小部队——仍有可能被遏制。",
  "Armistício no Sul": "南方停战",
  "Os governadores do Sul aceitam baixar as armas. Os estados rebelados voltam ao seu controle.": "南方州长们同意放下武器。叛乱的州回到你的控制之下。",
  "O exército separatista foi dissolvido.": "分离主义军队已被解散。",
  "Os governadores do Sul assinam o pacto: mais autonomia em troca de lealdade. A rebelião do Sul está descartada.": "南方州长们签署了协定：以忠诚换取更多自治。南方叛乱的可能已被排除。",
  "A Tensão no Sul deixa de importar: o Sul é seu aliado.": "南方紧张度不再重要：南方是你的盟友。",
  "A Liga do Sul cai": "南方联盟覆灭",
  "Não resta nenhum estado sob controle separatista. A revolta do Sul acabou.": "已没有任何州处于分离主义者控制之下。南方叛乱结束了。",
  "Cúpula de Porto Alegre": "阿雷格里港峰会",
  "Os governadores do Rio Grande do Sul, de Santa Catarina e do Paraná pedem uma reunião de emergência. Querem verbas, autonomia fiscal e garantias de que Brasília não mandará interventores.": "南里奥格兰德、圣卡塔琳娜和巴拉那的州长要求召开紧急会议。他们想要拨款、财政自治，以及巴西利亚不会派驻干预官的保证。",
  "Se nada mudar, dizem, não respondem pelo que a Liga do Sul fará.": "他们说，如果什么都不改变，他们无法为南方联盟的所作所为负责。",
  "Aceitar o acordo: verbas e autonomia fiscal para o Sul.": "接受协议：给南方拨款和财政自治。",
  "Prometer estudar as demandas.": "承诺研究这些诉求。",
  "Ameaçar com intervenção federal.": "以联邦干预相威胁。",
  "A Liga do Sul manda emissários": "南方联盟派来使者",
  "Os separatistas do Sul propõem um pacto de não agressão enquanto você enfrenta a resistência.": "南方分离主义者提议，在你对付抵抗力量期间签订互不侵犯条约。",
  "Ameaçar com uma ofensiva.": "以发动攻势相威胁。",
  "A Liga do Sul cobra a fatura": "南方联盟前来讨债",
  "Os separatistas exigem autonomia fiscal e comando próprio em troca da trégua.": "分离主义者要求财政自治和独立指挥权，作为休战的交换条件。",
  "Ceder e manter a trégua.": "让步，维持休战。",
  "Romper o pacto.": "撕毁协定。",
  "O que se temia acontece: o comando militar do Nordeste e unidades da Marinha declaram lealdade ao governo constitucional. Generais que antes hesitavam agora escolhem lados. Amazonas e Amapá passam para a resistência. E no Sul, os governadores do Rio Grande do Sul e de Santa Catarina — a chamada Liga do Sul — observam o racha e medem até onde Brasília ainda manda neles.": "人们担心的事情发生了：东北军区司令部和海军部队宣布效忠宪政政府。此前犹豫的将军们现在纷纷选边站。亚马孙和阿马帕倒向抵抗力量。而在南方，南里奥格兰德和圣卡塔琳娜的州长们——即所谓的南方联盟——冷眼旁观这场分裂，掂量着巴西利亚对他们还有多大的控制力。",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, a Liga do Sul mede forças com Brasília: se a tensão passar do limite, ela abre uma terceira frente.": "战线横穿米纳斯吉拉斯和巴伊亚西部。经济正在崩溃；成千上万的家庭逃往巴拉圭、玻利维亚和乌拉圭。在南方，南方联盟正与巴西利亚较劲：一旦紧张度越过极限，它就会开辟第三条战线。",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, o Pacto Federativo segura: as brigadas gaúchas e catarinenses lutam ao lado de Brasília.": "战线横穿米纳斯吉拉斯和巴伊亚西部。经济正在崩溃；成千上万的家庭逃往巴拉圭、玻利维亚和乌拉圭。在南方，联邦协定依然有效：南里奥格兰德和圣卡塔琳娜的旅与巴西利亚并肩作战。",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, a Liga do Sul abriu uma terceira frente.": "战线横穿米纳斯吉拉斯和巴伊亚西部。经济正在崩溃；成千上万的家庭逃往巴拉圭、玻利维亚和乌拉圭。在南方，南方联盟开辟了第三条战线。",
  "O cessar-fogo vira fronteira. Brasília controla o Centro-Sul e o Sul — os governadores sulistas nunca romperam —; o governo constitucional fica com o Norte e o Nordeste. Minas Gerais continua cortada por trincheiras.": "停火线变成了国界。巴西利亚控制中南部和南方——南方州长们从未决裂；宪政政府保有北部和东北部。米纳斯吉拉斯依然被战壕割裂。",
  "Duas Bandeiras": "两面旗帜",
  "A revolta da Liga do Sul foi esmagada: não resta estado sob controle separatista.": "南方联盟的叛乱已被镇压：没有任何州仍处于分离主义者控制之下。",
  "Pacto Federativo assinado: o Sul agora é aliado e enviou uma divisão.": "联邦协定已签署：南方现在是盟友，并派来了一个师。",
