  "Dificuldade": "难度",
  "Para quem nunca jogou estratégia: inimigo mais fraco, Sul mais calmo, mais Recursos e uma interface mais simples. Os exércitos lutam sozinhos.": "适合从未玩过策略游戏的人：敌人更弱，南方更平静，资源更多，界面更简单。军队自动作战。",
  "O jogo como foi pensado: decisões com peso e guerra equilibrada.": "按设计初衷的游戏体验：决策分量十足，战争势均力敌。",
  "Inimigo mais forte, menos Recursos e o Sul mais inquieto. Para quem já conhece o jogo.": "敌人更强，资源更少，南方更不安分。适合已经熟悉游戏的玩家。",
  "Recomendado para começar": "推荐入门",
  "Cerca de 12 a 20 meses de jogo (turnos). A história no ritmo normal.": "约 12 到 20 回合。故事按正常节奏展开。",
  "Cerca de 8 a 11 turnos (20 a 30 minutos). O tempo passa mais depressa e os eventos-chave chegam antes.": "约 8 到 11 回合（20 到 30 分钟）。时间流逝更快，关键事件来得更早。",
  "No Fácil, a interface fica mais simples: os exércitos agem sozinhos, a conversão de Recursos some e as escolhas que encerram a campanha avisam antes.": "简单难度下界面更简洁：军队自动行动，资源兑换被隐藏，会结束战役的选项会提前提醒。",
  "A dificuldade fica fixa até o fim da campanha. Você pode conferir qual é em Configurações.": "难度在战役结束前固定不变。你可以在设置中查看。",
  "Começar uma nova campanha substitui a campanha salva.": "开始新战役会覆盖已保存的战役。",
