  "— exércitos no automático, conversão de Recursos escondida e Diplomacia/Facções em “Mais”": "——军队自动行动，隐藏资源兑换，外交／派系收进“更多”",
  "A dificuldade e a duração são escolhidas ao começar uma campanha e não mudam no meio dela.": "难度和时长在开始战役时选定，中途不会改变。",
