  "← Voltar ao resumo simples": "← 返回简明概要",
  "Modo simples: seus exércitos agem sozinhos. Clique num estado para ver detalhes e agir nele.": "简洁模式：你的军队自动行动。点击一个州查看详情并采取行动。",
  "Modo simples: seus exércitos agem sozinhos. Toque num estado para ver detalhes e agir nele.": "简洁模式：你的军队自动行动。点按一个州查看详情并采取行动。",
  "⚠ Encerra a campanha agora": "⚠ 将立即结束战役",
  "🏁 Encerra a campanha agora": "🏁 将立即结束战役",
  "final intermediário": "中途结局",
  "No Fácil, a interface é simples: os exércitos agem sozinhos e Diplomacia e Facções ficam no botão “Mais”. Dá para mudar isso em Configurações.": "简单难度下界面很简洁：军队自动行动，外交和派系收在“更多”按钮里。可以在设置中更改。",
  "Exércitos no automático": "军队自动行动",
  "No modo simples, seus exércitos agem sozinhos todo mês: atacam onde a chance é boa e defendem o resto. Você só precisa recrutar quando quiser mais tropas.": "在简洁模式下，你的军队每月自动行动：在胜算大的地方进攻，其余防守。只有想要更多部队时才需要招募。",
  "Quer controlar cada exército? Clique em “Comandar manualmente”.": "想逐一指挥每支军队？点击“手动指挥”。",
