  "Desligada": "关闭",
  "Tem um acontecimento esperando sua resposta na aba História. O mês só avança depois que você escolher.": "“故事”页有一件事在等你回应。你做出选择后，月份才会推进。",
  "Um exército está sem ordem neste mês. Deixe as tropas agirem sozinhas: elas atacam onde a chance é boa e defendem o resto.": "有一支军队本月没有命令。让部队自动行动吧：它们会在胜算大的地方进攻，其余防守。",
  "Já fizemos o que dava neste mês. Quando estiver pronto, encerre o mês.": "这个月能做的我们都做了。准备好了就结束本月吧。",
  "Ordens automáticas ligadas: as tropas agem sozinhas todo mês.": "自动命令已开启：部队每月自动行动。",
  "Sua conselheira": "你的顾问",
  "Não precisa seguir: o × esconde as dicas até o próximo mês, e em Configurações dá para desligar.": "不必照做：× 可以把提示隐藏到下个月，也可以在设置中关闭。",
