  ". Arraste para dividir as tropas, ou use": "。拖动来分配部队，或使用",
  "Evitar a rebelião (Pacto Federativo) mantém uma frente só.": "避免叛乱（联邦协定）可以只保留一条战线。",
  "Abriu uma nova frente de batalha. Divida as tropas entre as frentes na aba Mapa.": "开辟了一条新战线。在“地图”页为各战线分配部队。",
  "Começou a guerra: abriu a linha de frente. Na aba Mapa, escolha a postura de cada frente (avançar, segurar ou recuar) — não gasta AP.": "战争开始了：战线已经展开。在“地图”页为每条战线选择姿态（进攻、坚守或后撤）——不消耗行动点。",
