  "A Liga do Sul se rebelou: Rio Grande do Sul rompe com Brasília e abre a Frente Sul": "南方联盟叛乱了：南里奥格兰德与巴西利亚决裂，开辟了南方战线",
  "A Liga do Sul se rebelou: Santa Catarina rompe com Brasília e abre a Frente Sul": "南方联盟叛乱了：圣卡塔琳娜与巴西利亚决裂，开辟了南方战线",
