  "a": "至",
  "Renovar a direita": "革新右翼",
  "Depois do revés, abrir espaço para nomes novos, moderar o discurso e reconquistar o centro.": "挫折之后，为新面孔腾出空间，缓和言论，重新赢得中间派。",
  "Aparece depois de um revés: ficar inelegível ou perder uma eleição.": "在遭遇挫折后出现：失去参选资格或输掉选举。",
  "Dobrar a aposta": "加倍下注",
  "Depois do revés, culpar o sistema e manter a base fiel em pé de guerra. Mais apoio nas ruas, menos pontes.": "挫折之后，把责任推给体制，让忠实的基本盘保持战斗状态。街头支持更多，桥梁更少。",
  "Canal secreto com o inimigo": "与敌方的秘密渠道",
  "Emissários discretos negociam pausas locais e troca de prisioneiros. Alivia o desgaste sem admitir derrota.": "低调的使者谈判局部停火和交换战俘。缓解消耗，又不承认失败。",
