  "Caravana de comícios": "集会车队",
  "Aproveitar a popularidade com uma caravana pelo interior: transforma apoio difuso em base organizada.": "借着人气组织车队巡游内陆：把松散的支持变成有组织的基本盘。",
  "Aparece com Apoio Popular 55 ou mais.": "民众支持达到 55 或以上时出现。",
  "Pacto com os governadores do Sul": "与南方州长的协定",
  "Verbas, cargos e autonomia administrativa para acalmar o Rio Grande do Sul, Santa Catarina e o Paraná.": "拨款、职位和行政自治，以安抚南里奥格兰德、圣卡塔琳娜和巴拉那。",
  "Aparece quando a Tensão no Sul passa de 55 (antes de qualquer rebelião).": "当南方紧张度超过 55 时出现（在任何叛乱之前）。",
  "Capitalizar a popularidade": "把人气变现",
  "A maré está a seu favor: transformar a popularidade em doações e filiações antes que ela passe.": "形势对你有利：趁人气消退之前，把它转化为捐款和党员。",
  "o Apoio Popular passa de 60.": "民众支持超过 60。",
