  "Explorar um escândalo do governo": "利用政府丑闻",
  "Uma denúncia contra o governo domina o noticiário. Explorar a crise rende apoio, se a acusação se sustentar.": "一项针对政府的指控占据了新闻头条。如果指控站得住脚，利用这场危机就能赢得支持。",
  "um escândalo atinge o governo (na oposição, de vez em quando).": "政府遭遇丑闻（在野时，偶尔发生）。",
  "um escândalo atinge o governo (na oposição, de vez em quando)": "政府遭遇丑闻（在野时，偶尔发生）",
  "A denúncia não se sustenta e o feitiço vira contra o feiticeiro.": "指控站不住脚，攻击反而引火烧身。",
  "Pacote de emergência": "紧急方案",
  "Empréstimos de aliados, venda de ativos e cortes de última hora para fechar as contas.": "盟友贷款、出售资产和临时削减开支，以平衡账目。",
  "os Recursos caem para 6 ou menos.": "资源降到 6 或更少。",
  "os Recursos caem para 6 ou menos": "资源降到 6 或更少",
  "Jantar com os comandantes": "与司令官共进晚餐",
  "Uma noite discreta com generais indecisos. Promessas de cargos e verbas fecham apoios para a ruptura.": "与犹豫不决的将军们度过一个低调的夜晚。职位和经费的承诺为断裂锁定了支持。",
  "você está no caminho do golpe (depois da reunião secreta com os militares).": "你走上了政变之路（在与军方秘密会面之后）。",
  "você está no caminho do golpe (depois da reunião secreta com os militares)": "你走上了政变之路（在与军方秘密会面之后）",
  "Um convidado conta tudo a um jornalista.": "一位客人把一切都告诉了记者。",
  "Defesa em profundidade": "纵深防御",
  "Cavar trincheiras, reorganizar a retaguarda e devolver o moral às tropas depois de um revés.": "挖掘战壕，重整后方，在挫折后恢复部队士气。",
