  "✨ Novo foco disponível (aba Decisões)": "✨ 有新国策可用（“决策”页）",
  "aberta por um evento": "由事件开启",
  "Oportunidade passada": "机会已过",
  "Oportunidade fechada": "机会已关闭",
  "Apareceu uma oportunidade na aba Decisões e ela some no fim do mês. Vale aproveitar:": "“决策”页出现了一个机会，月底就会消失。值得把握：",
  "Oportunidades e focos novos": "机会和新国策",
  "Oportunidade (aparece e expira)": "机会（会出现也会过期）",
  "Novo neste turno": "本回合新增",
  "Novos focos ou oportunidades": "新国策或机会",
  "NOVO": "新",
  "NOVA": "新",
  "oportunidade": "机会",
  "depende do momento": "视时机而定",
  "novo": "新",
  "Oportunidades (⚡)": "机会（⚡）",
  "Focos curtos que abrem quando a situação permite e somem em poucos meses se você não aproveitar. Muitos voltam mais tarde.": "在形势允许时开启的短期国策，如果不把握，几个月内就会消失。许多之后还会再出现。",
  "Sem prazo": "无时间限制",
  "Cansaço da guerra": "厌战情绪",
  "Cansaço da guerra:": "厌战情绪：",
  "Depois de 12 meses de combate, o Apoio Popular cai aos poucos e as frentes ficam mais voláteis, para que o impasse se resolva.": "作战 12 个月后，民众支持会逐渐下降，战线也会变得更不稳定，以打破僵局。",
  "Projetos de 1 ou 2 meses, um por vez. Ao concluir, aplicam efeitos e liberam opções. Alguns só aparecem em certos momentos (guerra longa, Tensão no Sul alta, apoio alto, depois de um revés) — o jogo avisa com ✨.": "为期 1 或 2 个月的项目，一次一个。完成后产生效果并开启新选项。有些只在特定时刻出现（长期战争、南方紧张度高、支持高、遭遇挫折后）——游戏会用 ✨ 提示。",
  "aparecem conforme a situação (apoio alto, caixa vazio, guerra longa…) e": "会根据形势出现（支持高、国库空虚、长期战争……），并且",
  "somem em poucos meses": "几个月内就会消失",
  ". Ficam na coluna laranja e nesta faixa, com a contagem regressiva.": "。它们显示在橙色列和这条横栏中，并带有倒计时。",
  "Ficam na coluna laranja e nesta faixa, com a contagem regressiva.": "它们显示在橙色列和这条横栏中，并带有倒计时。",
  "Quando um foco novo fica disponível, ele ganha a etiqueta": "新国策可用时，会带有标签",
  "e a aba mostra": "，页签上会显示",
  "meses de combate — Apoio Popular cai aos poucos e as frentes se movem": "个月的战斗——民众支持逐渐下降，战线移动",
  ". Tréguas pausam o desgaste.": "。休战会暂停消耗。",
  "Tréguas pausam o desgaste.": "休战会暂停消耗。",
  "Nenhuma aberta agora — elas aparecem conforme a situação (apoio alto, caixa vazio, guerra longa…).": "目前没有开启的机会——它们会根据形势出现（支持高、国库空虚、长期战争……）。",
  "Inimigo mais forte, menos Recursos, o Sul mais inquieto, popularidade alta que se desgasta e só uma revanche nas urnas. Para quem já conhece o jogo.": "敌人更强，资源更少，南方更不安分，高人气会逐渐消退，选票翻盘只有一次机会。适合已经熟悉游戏的玩家。",
  "Investir pesado nas campanhas.": "在竞选中大量投入。",
  "Mandá-los para a defesa civil.": "派他们去参加民防。",
  "(uma vez só)": "（仅一次）",
  "Nenhuma aberta agora. Elas aparecem conforme a situação (apoio, guerra, caixa, Sul…) e somem se você não aproveitar.": "目前没有开启的机会。它们会根据形势出现（支持、战争、国库、南方……），如果不把握就会消失。",
  "aparece quando um escândalo atinge o governo (na oposição, de vez em quando).": "在政府遭遇丑闻时出现（在野时，偶尔发生）。",
  "Aparece quando um escândalo atinge o governo (na oposição, de vez em quando)": "在政府遭遇丑闻时出现（在野时，偶尔发生）",
  "● Oportunidade": "● 机会",
  "sem comando": "无指挥",
  "Detalhes do foco": "国策详情",
  "● Disponível": "● 可用",
  "Exclusivo com": "互斥于",
  "Cancelar o foco atual? Ele começou neste turno, então o ponto de ação e os Recursos gastos para iniciá-lo serão devolvidos.": "取消当前国策？它是本回合开始的，所以启动时花费的行动点和资源会退还。",
  "Cancelar o foco atual? O progresso será perdido e, como ele começou num turno anterior, o ponto de ação e os Recursos gastos não serão devolvidos.": "取消当前国策？进度将会丢失；由于它是在之前的回合开始的，花费的行动点和资源不会退还。",
  "Foco cancelado": "国策已取消",
  "Ponto de ação e Recursos devolvidos.": "行动点和资源已退还。",
  "Ponto de ação e Recursos devolvidos": "行动点和资源已退还",
  "O progresso foi perdido (começou num turno anterior, nada foi devolvido).": "进度已丢失（在之前的回合开始，未退还任何东西）。",
  "O progresso foi perdido (começou num turno anterior, nada foi devolvido)": "进度已丢失（在之前的回合开始，未退还任何东西）",
  "Mapa de guerra do Brasil por facção, com as frentes e o placar de força de cada uma. Use Tab para percorrer os estados; a descrição em texto está no botão Descrição do mapa.": "按派系划分的巴西战争地图，显示各条战线及其兵力比分牌。用 Tab 键依次浏览各州；文字描述在“地图描述”按钮里。",
  "sem combate ainda": "尚未交战",
  "no último mês a linha quase não mexeu": "上月战线几乎没动",
  "no último mês a linha avançou": "上月战线推进了",
