  "No mapa: a linha de frente é a borda grossa laranja; faixas listradas mostram o seu lado e o lado inimigo; cada frente tem um placar com a sua força e a do inimigo.": "地图上：战线是粗橙色边界；条纹带表示我方和敌方；每条战线都有一块比分牌，显示你和敌人的兵力。",
  "O placar na linha mostra a sua força contra a do inimigo; toque nele para abrir a frente.": "战线上的比分牌显示你对敌人的兵力；点按它可打开该战线。",
