  "Suas regiões": "你的地区",
  "Regiões inimigas": "敌方地区",
  "Você não move exércitos: escolha a postura de cada frente e encerre o mês.": "你不调动军队：为每条战线选择姿态，然后结束本月。",
  ", da economia, das tropas no estado e de haver guerra por perto.": "、经济、该州驻军以及附近是否有战斗。",
  "O governador de um estado na linha de frente manda emissários: aceita apoiar o regime em troca de verbas e cargos.": "一个前线州的州长派来使者：愿意支持政权，以换取拨款和职位。",
  "Capital e reduto só caem com o cerco completo; enquanto isso, a linha toma as regiões em volta.": "首都和据点只有在包围完成后才会陷落；在此之前，战线会夺取周围的地区。",
