  "A batalha foi equilibrada, mas você venceu e tomou o estado.": "战斗势均力敌，但你获胜并夺取了这个州。",
  "Você estava mais fraco, mas teve sorte e tomou o estado.": "你兵力较弱，但运气好，夺取了这个州。",
  "O inimigo atacou com força bem maior: o estado caiu.": "敌人以远超你的兵力进攻：这个州失守了。",
  "A sua defesa era boa, mas o inimigo teve sorte: o estado caiu.": "你的防守不错，但敌人运气好：这个州失守了。",
  "Ataque o mesmo estado vindo de dois estados diferentes: as forças se somam e ainda ganham bônus de flanco.": "从两个不同的州进攻同一个州：兵力叠加，还能获得侧翼加成。",
  "Deixe um exército parado no estado ameaçado: entrincheirado ele defende +20%.": "在受威胁的州留一支军队：据守时防御 +20%。",
  "Recrute num estado seu ou reforce um exército que já existe.": "在你控制的州招募，或增援现有军队。",
  "Ataque de dois lados ao mesmo tempo: o bônus de flanco pode virar a batalha.": "同时从两侧进攻：侧翼加成可以扭转战局。",
  "Cerque: tome os estados por trás de um exército inimigo e ele fica sem ligação com a capital — perde força e se rende.": "包围：夺取敌军身后的州，它就与首都失去联系——兵力下降并投降。",
  "Nenhum estado mudou de lado no último mês.": "上个月没有州易手。",
