  "O bônus de flanco fica 2,5× maior. Ataque de 2 ou 3 estados vizinhos.": "侧翼加成提高到 2.5 倍。从 2 或 3 个相邻州进攻。",
  "Desembarca pelo porto e evita as fortificações (sem bônus de reduto), mas com −15% de força.": "从港口登陆，绕开防御工事（没有要塞加成），但兵力 −15%。",
  "Batalha de Recife": "累西腓战役",
  "Escolha a tática do ataque final": "选择最后进攻的战术",
  "A Resistência fará a última resistência: +15% na defesa.": "抵抗力量将进行最后抵抗：防御 +15%。",
