  "Formar nova divisão": "组建新师",
  "Soldo pago de novo: os quartéis se acalmam.": "军饷重新发放：军营平静下来。",
  "Sem dinheiro para pagar o soldo, as tropas se amotinaram e abandonaram o regime.": "没钱发军饷，部队哗变并抛弃了政权。",
  "Atenção ao soldo: se os Recursos ficarem muito negativos por meses seguidos, as tropas se amotinam.": "注意军饷：如果资源连续数月严重为负，部队就会哗变。",
