  "Cancelar o foco atual? Ele começou neste turno, então os Recursos gastos para iniciá-lo serão devolvidos.": "取消当前国策？它是本回合开始的，因此启动时花费的资源将被退还。",
  "Cancelar o foco atual? O progresso será perdido e, como ele começou num turno anterior, os Recursos gastos não serão devolvidos.": "取消当前国策？进度将丢失，而且由于它是在之前的回合开始的，花费的资源不会退还。",
  "grátis, sem gastar ações.": "免费，不消耗行动。",
  "grátis, sem gastar ações": "免费，不消耗行动",
  "Projetos de 1 ou 2 meses, um por vez. Não gastam ações políticas. Ao concluir, aplicam efeitos e liberam opções. Alguns só aparecem em certos momentos (guerra longa, Tensão no Sul alta, apoio alto, depois de um revés) — o jogo avisa com ✨.": "为期1或2个月的项目，一次一个。不消耗政治行动点。完成后产生效果并解锁选项。有些只在特定时刻出现（长期战争、南方紧张度高、支持度高、遭遇挫折之后）——游戏会用✨提示。",
  ": ações e propostas diplomáticas (facções são pagas só com Recursos políticos).": "：行动和外交提议（派系只用政治资源支付）。",
  ": ações e propostas diplomáticas, agradar ou enfraquecer facções.": "：行动、外交提议、安抚或削弱派系。",
