  "— não gasta ações políticas; ele avança a cada mês e, ao concluir, aplica efeitos e libera ações, eventos e opções.": "——不消耗政治行动点；它每月推进，完成后产生效果并解锁行动、事件和选项。",
  "Toque no": "点击",
  "para ver as regras gerais e o efeito de": "查看总体规则以及以下操作的效果：",
  "Cada cartão mostra o que a facção faz em cada nível de lealdade; a linha": "每张卡片显示该派系在各忠诚度等级下的作用；",
  "destacada (▸)": "高亮（▸）的一行",
  "é o efeito de agora. Embaixo de cada botão aparece o resultado (ou por que está bloqueado).": "是当前效果。每个按钮下方显示结果（或被锁定的原因）。",
