  "num país dividido, com inflação acima de {0}% ao ano e resistência armada possível no Rio Grande do Sul.": "这个国家四分五裂，年通胀率超过 {0}%，南里奥格兰德可能出现武装抵抗。",
  "O mapa usa a divisão atual dos estados; passe o mouse para ver a situação de {0}.": "地图采用现今的州划分；将鼠标悬停可查看 {0} 年的局势。",
