  "{0} de outubro de {1}": "{1}年10月{0}日",
  "O TSE confirma a derrota no {0}º turno por {1} ponto. Reconhecer o resultado, contestar, ficar em silêncio — ou tentar romper a ordem constitucional? Instituições, quartéis, ruas e o mundo vão reagir.": "高等选举法院确认你在第 {0} 轮以 {1} 个百分点之差落败。承认结果、提出异议、保持沉默——还是试图打破宪政秩序？国家制度、军营、街头和全世界都会作出反应。",
  "Finais descobertos: {0}/{1}": "已解锁结局：{0}/{1}",
  "Seu: Batalhão da Guarda Presidencial, força {0} em DF": "你方：总统卫队营，兵力 {0}，位于 DF",
  "Maioria Lula ({0}º turno) ({1})": "卢拉占多数（第 {0} 轮）（{1}）",
  "Maioria Bolsonaro ({0}º turno) ({1})": "博索纳罗占多数（第 {0} 轮）（{1}）",
  "Goulart caiu. Você comanda o governo instalado pelos militares. Devolver o poder aos civis em {0} ou endurecer com atos institucionais, cassações e censura? Linha dura, Congresso, Igreja, estudantes, o Sul de Brizola e Washington vão pressionar.": "古拉特倒台了。你领导着军方扶植的政府。是在 {0} 年把权力交还文官，还是以制度法令、褫夺政治权利和审查来强化统治？强硬派、国会、教会、学生、布里佐拉的南方和华盛顿都会施压。",
  "Jogar {0} — A Faixa Presidencial": "开始 {0} — 总统绶带",
