  "Cenário {0}": "{0} 剧本",
  "E se a noite de {0} de outubro de {1} tivesse terminado de outro jeito?": "如果 {1} 年 10 月 {0} 日的那个夜晚有了不同的结局，会怎样？",
  "{0} de outubro de {1}. A apuração termina com a menor margem da história recente: o candidato da oposição vence o {2}º turno com {3}% dos votos válidos. Você joga como o presidente derrotado, Jair Bolsonaro, nas horas e meses seguintes.": "{1} 年 10 月 {0} 日。计票以近年来最小的差距结束：反对派候选人以 {3}% 的有效票赢得第 {2} 轮。你扮演落败的总统雅伊尔·博索纳罗，经历接下来的数小时和数月。",
  "O mapa começa com o resultado real do {0}º turno em cada estado. A partir da primeira decisão, a história se torna alternativa: suas escolhas movem o apoio popular, os quartéis, o Congresso e o olhar do mundo — e podem levar o país da transição pacífica à ruptura e até a uma guerra de separação.": "地图以第 {0} 轮各州的真实结果开局。从第一个决定开始，历史就变成了架空：你的选择会影响民众支持、军营、国会和世界的目光——并可能把国家从和平交接引向断裂，甚至一场分裂战争。",
  "Finais descobertos: {0} de {1}": "已解锁结局：{0}/{1}",
