  "O TSE conclui a totalização pouco depois da meia-noite: {0}% dos votos válidos para o candidato da oposição, {1}% para você. É a disputa presidencial mais apertada desde a redemocratização — pouco mais de dois milhões de votos de diferença.": "高等选举法院在午夜后不久完成汇总：反对派候选人获得 {0}% 的有效票，你获得 {1}%。这是民主化以来最胶着的总统选举——差距仅略多于两百万票。",
