  "Abaixo de zero, você perde {0} de Apoio Popular por mês.": "低于零时，你每月失去 {0} 民众支持。",
  "Pontos de ação do turno. Quase tudo custa {0} AP. Recarregam a cada mês e não acumulam. Em {1}: {2} de base, {3} com Apoio Popular {4}+, {5} com {6}+; +{7} comprando com Recursos ({8}×/turno).": "本回合的行动点。几乎所有事都花费 {0} 行动点。每月恢复，不能累积。在 {1}：基础 {2}，民众支持 {4}+ 时为 {3}，{6}+ 时为 {5}；用资源购买 +{7}（每回合 {8} 次）。",
  "opinião pública. Alto acalma os estados e, em {0}, dá mais ações por turno ({1}+ → {2}, {3}+ → {4}); baixo alimenta protestos e revoltas. Se chegar a zero, a campanha termina.": "舆论。高时可安抚各州，在 {0} 时每回合行动更多（{1}+ → {2}，{3}+ → {4}）；低时会助长抗议和暴动。降到零，战役就结束。",
  "Tensão em cada estado ({0}–{1}). Média acima de {2} nos seus estados derruba o apoio; um estado acima de {3} sem tropas pode se revoltar. Investir, fazer propaganda e negociar com o governador baixam a agitação.": "各州的紧张程度（{0}–{1}）。你各州平均值高于 {2} 会拉低支持；无驻军且高于 {3} 的州可能暴动。投资、宣传和与州长谈判可降低动荡。",
  "Lealdade (do seu lado?) e influência (quanto pesam). Lealdade abaixo de {0} com influência {1} ou mais gera crises.": "忠诚度（是否站在你这边）和影响力（分量多大）。忠诚度低于 {0} 且影响力达到 {1} 或以上会引发危机。",
