  ": opinião pública. Alto acalma os estados e, em {0}, dá mais ações por turno ({1}+ → {2}, {3}+ → {4}); baixo alimenta protestos e revoltas.": "：舆论。高时可安抚各州，在 {0} 时每回合行动更多（{1}+ → {2}，{3}+ → {4}）；低时会助长抗议和暴动。",
  "Vão de {0} a {1}.": "范围从 {0} 到 {1}。",
  "Cria um novo exército por alguns Recursos, sem AP (até {0} por mês). Exércitos fracos em descanso no seu território também se reforçam sozinhos.": "花费一些资源组建新军队，不消耗行动点（每月最多 {0} 支）。在本方领土休整的弱小军队也会自行补充。",
  "({0} AP); ele avança a cada mês e, ao concluir, aplica efeitos e libera ações, eventos e opções.": "（{0} 行动点）；它每月推进，完成后产生效果并开启行动、事件和选项。",
  "lealdade abaixo de {0} com influência {1} ou mais provoca uma": "忠诚度低于 {0} 且影响力达到 {1} 或以上会引发",
  "que têm de você (−{0} a +{1}). Escolha um para negociar.": "——对你的看法（−{0} 到 +{1}）。选择一个进行谈判。",
  "mostra a chance antes de propor ({0} AP). A": "会在提议前显示成功率（{0} 行动点）。",
  "Você não impediu a transição. A equipe do presidente eleito assume os ministérios e, em {0}º de janeiro, a faixa presidencial muda de dono. O comando do país começa a escapar das suas mãos.": "你没有阻止权力交接。当选总统的团队接管了各部委，{0} 月 1 日，总统绶带易主。国家的指挥权开始从你手中溜走。",
  "A posse acontece em {0}º de janeiro. Uma semana depois, milhares de manifestantes invadem e depredam as sedes do Congresso, do Planalto e do STF. As imagens correm o mundo; líderes estrangeiros condenam o ataque em uníssono.": "就职典礼在 1 月 {0} 日举行。一周后，数千名抗议者冲进并打砸国会、总统府和最高法院。画面传遍全球；外国领导人一致谴责这次袭击。",
  "O Brasil, que entrou em {0} como um país polarizado, agora corre o risco de não ser mais um país.": "以两极分化国家的姿态进入 {0} 年的巴西，如今面临不再是一个国家的危险。",
  "Por maioria, o tribunal declara você inelegível por oito anos. A decisão cai como uma bomba na direita: governadores, pastores, empresários e deputados começam a se perguntar quem herdará os seus votos em {0}.": "法院以多数票宣布你八年内不得参选。这个决定在右翼中如同炸弹：州长、牧师、企业家和议员们开始思考，{0} 年谁会继承你的选票。",
