  "o golpe em si, o racha nas Forças (+{0} de uma vez), agitação alta em RS/SC/PR, agronegócio insatisfeito, Apoio Militar baixo (<{1}), ameaças e intervenções.": "政变本身、武装部队分裂（一次性 +{0}）、RS/SC/PR 动荡高企、农业综合企业不满、军方支持偏低（<{1}）、威胁和干预。",
  "(−{0}) em RS/SC/PR no mapa, exércitos seus estacionados no Sul, agradar o agronegócio e escolher negociar nos eventos.": "（−{0}）在地图上的 RS/SC/PR、驻扎在南方的军队、拉拢农业综合企业，以及在事件中选择谈判。",
  "e, com a tensão em {0} ou menos, assine o": "并在紧张度为 {0} 或以下时签署",
  "Ela começou só pelo Rio Grande do Sul, com um exército pequeno (força {0}). Se a tensão ficar acima de {1}, Santa Catarina adere.": "叛乱起初只在南里奥格兰德，军队规模很小（兵力 {0}）。如果紧张度保持在 {1} 以上，圣卡塔琳娜会加入。",
  "Se você baixar a tensão para {0} ou menos, ela aceita um armistício": "如果你把紧张度降到 {0} 或以下，它会接受停战",
  "Rio Grande do Sul passou para a Liga do Sul, com um exército de força {0}.": "南里奥格兰德倒向了南方联盟，带着一支兵力 {0} 的军队。",
  "Se a tensão ficar acima de {0} por {1} meses, Santa Catarina também adere.": "如果紧张度连续 {1} 个月高于 {0}，圣卡塔琳娜也会加入。",
  "Saída política: baixe a Tensão no Sul para {0} ou menos (ações da categoria Sul, investir/negociar em RS/SC/PR) e eles aceitam um armistício.": "政治出路：把南方紧张度降到 {0} 或以下（南方类行动、在 RS/SC/PR 投资／谈判），他们就会接受停战。",
  "A tensão recomeça em {0}. Cuide dela para não haver uma segunda revolta.": "紧张度从 {0} 重新开始。注意控制，以免再次叛乱。",
  "Na guerra, a Divisão Blindada do Sul (força {0}) luta do seu lado.": "战争中，南方装甲师（兵力 {0}）站在你这边作战。",
  "Tensão no Sul: {0} → {1}. Clique na barra “Tensão no Sul” para ver como baixá-la.": "南方紧张度：{0} → {1}。点击“南方紧张度”进度条查看如何降低。",
  "Só se a Liga do Sul se rebelar (Tensão no Sul chega a {0}).": "仅当南方联盟叛乱时（南方紧张度达到 {0}）。",
  "Trégua de conveniência com os separatistas: reconhece fato consumado e divide o comando. Derruba a Tensão no Sul (−{0}), o que pode levar a um armistício.": "与分离主义者达成权宜休战：承认既成事实并分享指挥权。大幅降低南方紧张度（−{0}），可能促成停战。",
  "Tensão no Sul {0}": "南方紧张度 {0}",
