  "O Sul vira aliado (+{0} exército de {1})": "南方成为盟友（+{0} 支兵力 {1} 的军队）",
  "⚠ Tensão no Sul em {0}/{1} (+{2} no turno): no ritmo atual a Liga do Sul se rebela em ~{3} meses. Use as ações da categoria Sul (aba Ações) ou invista em RS/SC/PR.": "⚠ 南方紧张度 {0}/{1}（本回合 +{2}）：按目前的速度，南方联盟约 {3} 个月后叛乱。使用南方类行动（“行动”页）或在 RS/SC/PR 投资。",
  "⚠ Tensão no Sul em {0}/{1} (-{2} no turno): no ritmo atual a Liga do Sul se rebela em ~{3} meses. Use as ações da categoria Sul (aba Ações) ou invista em RS/SC/PR.": "⚠ 南方紧张度 {0}/{1}（本回合 -{2}）：按目前的速度，南方联盟约 {3} 个月后叛乱。使用南方类行动（“行动”页）或在 RS/SC/PR 投资。",
  "⚠ Tensão no Sul em {0}/{1} (+{2} no turno). Use as ações da categoria Sul (aba Ações) ou invista em RS/SC/PR.": "⚠ 南方紧张度 {0}/{1}（本回合 +{2}）。使用南方类行动（“行动”页）或在 RS/SC/PR 投资。",
  "A Liga do Sul se rebelou: Rio Grande do Sul rompe com Brasília (um exército separatista pequeno, força {0}). Santa Catarina pode aderir em {1} meses se a tensão continuar alta.": "南方联盟叛乱了：南里奥格兰德与巴西利亚决裂（一支小规模分离主义军队，兵力 {0}）。如果紧张度居高不下，圣卡塔琳娜可能在 {1} 个月内加入。",
  "A Liga do Sul segue em revolta (tensão {0}/{1}). Se continuar acima de {2}, Santa Catarina adere em breve. Com {3} ou menos, ela aceita um armistício.": "南方联盟仍在叛乱（紧张度 {0}/{1}）。如果保持在 {2} 以上，圣卡塔琳娜很快会加入。降到 {3} 或以下，它会接受停战。",
  "A Liga do Sul segue em revolta (tensão {0}/{1}). Com {2} ou menos, ela aceita um armistício.": "南方联盟仍在叛乱（紧张度 {0}/{1}）。降到 {2} 或以下，它会接受停战。",
  "Santa Catarina adere à Liga do Sul (tensão {0}/{1}). Baixe a tensão para {2} ou menos para forçar um armistício.": "圣卡塔琳娜加入南方联盟（紧张度 {0}/{1}）。把紧张度降到 {2} 或以下以迫使停战。",
  "Armistício no Sul: a Liga do Sul depõe as armas e os estados rebeldes voltam ao seu controle. Tensão no Sul {0}/{1} — se voltar a {2}, ela se rebela de novo.": "南方停战：南方联盟放下武器，叛乱的州回到你的控制之下。南方紧张度 {0}/{1}——如果再次达到 {2}，它会再次叛乱。",
  "O racha nas Forças inflama o Sul: Tensão no Sul +{0} (agora {1}/{2}).": "武装部队的分裂点燃了南方：南方紧张度 +{0}（现为 {1}/{2}）。",
  "Tensão no Sul: {0}/{1} (+{2}).": "南方紧张度：{0}/{1}（+{2}）。",
  "Tensão no Sul: {0}/{1} (-{2}).": "南方紧张度：{0}/{1}（-{2}）。",
  "Tensão no Sul: {0}/{1} ({2}).": "南方紧张度：{0}/{1}（{2}）。",
  "aqui baixa a Tensão no Sul em {0}, e": "在这里可使南方紧张度降低 {0}，而",
  "com sucesso, em {0}.": "成功时降低 {0}。",
