  "Avança sobre um estado vizinho inimigo ou em disputa. Gasta {0} manobra. Vários exércitos atacando o mesmo estado somam forças.": "向相邻的敌方或争夺中的州推进。消耗 {0} 次机动。多支军队进攻同一州时兵力叠加。",
  ": Avança sobre um estado vizinho inimigo ou em disputa. Gasta {0} manobra. Vários exércitos atacando o mesmo estado somam forças.": "：向相邻的敌方或争夺中的州推进。消耗 {0} 次机动。多支军队进攻同一州时兵力叠加。",
  "Leva o exército para um estado vizinho seu (ou recua de uma frente). Gasta {0} manobra.": "把军队调往你相邻的州（或从战线后撤）。消耗 {0} 次机动。",
  ": Leva o exército para um estado vizinho seu (ou recua de uma frente). Gasta {0} manobra.": "：把军队调往你相邻的州（或从战线后撤）。消耗 {0} 次机动。",
  "Fica onde está, com posições preparadas: +{0}% na defesa e +{1} de moral. Não gasta manobra.": "原地据守预设阵地：防守 +{0}%，士气 +{1}。不消耗机动。",
  ": Fica onde está, com posições preparadas: +{0}% na defesa e +{1} de moral. Não gasta manobra.": "：原地据守预设阵地：防守 +{0}%，士气 +{1}。不消耗机动。",
  "Fica parado e ganha +{0} de força no fim do mês. Custa dinheiro, só em território seu. Não gasta manobra.": "原地不动，月底兵力 +{0}。需要花钱，仅限本方领土。不消耗机动。",
