  "(metade das regiões do estado passa para o inimigo); fora dela, grandes protestos (−{0} de apoio) ou até perder o estado.": "（该州一半的地区倒向敌人）；在战争之外，则是大规模抗议（支持 −{0}），甚至失去该州。",
