  "No começo da campanha cada turno é uma quinzena ({0} dias): mais decisões antes da posse. Depois, cada turno vira um mês.": "战役开始时，每回合为半个月（{0} 天）：就职前能做更多决定。之后，每回合变为一个月。",
  "Contestação das urnas: progresso {0}/{1} (+{2}) · credibilidade {3} · escalada {4}.": "选举结果质疑：进度 {0}/{1}（+{2}）· 公信力 {3} · 升级值 {4}。",
  "Contestação das urnas: progresso {0}/{1} · credibilidade {2} · escalada {3}.": "选举结果质疑：进度 {0}/{1} · 公信力 {2} · 升级值 {3}。",
  "Contestação das urnas: progresso {0} de {1}, credibilidade {2}, escalada {3}. Abrir detalhes.": "选举结果质疑：进度 {0}/{1}，公信力 {2}，升级值 {3}。打开详情。",
  "Julgamento no TSE: precisa de {0}": "高等选举法院裁决：需要 {0}",
  "Veredito: precisa de {0}": "最终裁决：需要 {0}",
  "Chegue a {0} para vencer": "达到 {0} 即可获胜",
  "Seu progresso está baixo para o julgamento de janeiro ({0}/{1}). Auditoria, ações no TSE e o Congresso rendem mais com credibilidade alta.": "你的进度不足以应对一月的裁决（{0}/{1}）。公信力越高，审计、向法院起诉和国会的效果越好。",
  "As ruas estão no limite (escalada {0}). Mais um ato e os acampamentos viram caso de quartel. Use 'Baixar a temperatura' agora.": "街头已到极限（升级值 {0}）。再来一次集会，营地就会变成军营的事。现在就用“降温”。",
  "Sua credibilidade está em {0}. Abaixo de zero, o TSE declara você inelegível. Pare com as redes e traga observadores ou peritos.": "你的公信力为 {0}。降到零以下，高等选举法院就会宣布你丧失参选资格。停止网络攻势，请观察员或专家来。",
  "Está funcionando: {0}/{1} de progresso, credibilidade {2}, escalada {3}. Mantenha a frente dentro da lei.": "奏效了：进度 {0}/{1}，公信力 {2}，升级值 {3}。让阵线保持在法律框架内。",
  "Agora é pelas regras, mas é guerra de nervos. Três números: o progresso vence em {0}; a credibilidade não pode zerar, ou o TSE te torna inelegível; e a escalada não pode chegar a {1}, ou as ruas viram caso de quartel.": "现在要按规则来，但这是一场神经战。三个数字：进度到{0}就赢；公信力不能归零，否则高等选举法院会让你丧失参选资格；升级值不能到{1}，否则街头就会变成军营的事。",
  "O TSE adiou a posse para auditar as seções. Até março, cada quinzena conta: leve o progresso a {0} sem perder a credibilidade.": "高等选举法院推迟了就职以审计投票站。到三月为止，每个半月都很关键：在不失去公信力的情况下把进度推到{0}。",
  "Você está tentando virar o resultado sem guerra: auditorias, tribunais, Congresso e ruas, sempre dentro da lei. São três números de {0} a {1}:": "你正试图不打仗就扭转结果：审计、法院、国会和街头，始终在法律框架内。共有三个数字，范围 {0} 到 {1}：",
